use super::*;
use mc4d_core::{block,camera::Orientation,chunk::Chunk};
#[test]
#[ignore="requires GPU; validates native particle textures, geometry occlusion, 4D inset isolation, stereo and resize"]
fn particles_are_textured_occluded_and_confined_to_their_slice(){
 let instance=wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle_from_env());let adapter=pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions{power_preference:wgpu::PowerPreference::HighPerformance,compatible_surface:None,force_fallback_adapter:false,apply_limit_buckets:false})).unwrap();let(device,queue)=pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor{required_limits:adapter.limits(),..Default::default()})).unwrap();
 let size=(512,320);let format=wgpu::TextureFormat::Rgba8UnormSrgb;let mut renderer=Renderer::new(&device,format,size);let mut world=World::new(7,None);world.insert_chunk(IVec4::ZERO,Chunk::uniform(block::AIR));for w in 0..16{for y in 0..16{for x in 0..16{world.set_block(IVec4::new(x,y,10,w),block::STONE);}}}crate::gpu_tests::settle_lighting(&mut world,&[IVec4::ZERO]);
 let eye=Vec4::new(8.0,4.0,4.0,8.0);renderer.sync_world(&device,&queue,&world,eye,&[IVec4::ZERO]);let basis=Orientation::default().basis();let views:Vec<_>=mc4d_core::views::slice_bases(basis,2).into_iter().zip(mc4d_core::views::view_rects([size.0 as f32,size.1 as f32],2)).map(|(basis,rect)|ViewDraw{basis,rect}).collect();
 let target=device.create_texture(&wgpu::TextureDescriptor{label:Some("particle proof"),size:wgpu::Extent3d{width:size.0,height:size.1,depth_or_array_layers:1},mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format,usage:wgpu::TextureUsages::RENDER_ATTACHMENT|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});let view=target.create_view(&Default::default());let read=device.create_buffer(&wgpu::BufferDescriptor{label:None,size:(size.0*size.1*4)as u64,usage:wgpu::BufferUsages::COPY_DST|wgpu::BufferUsages::MAP_READ,mapped_at_creation:false});let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/render-review");std::fs::create_dir_all(&root).unwrap();
 let render=|renderer:&mut Renderer,particles:&[ParticleDraw],flags:u32,name:&str|{
  let params=FrameParams{particles,first_person:None,eye,basis,fov_y_deg:65.0,max_dist:32.0,target:None,entities:&[],flags,ghost_offset:1.0,glasses_range:8.0,time:0.0,break_progress:0.0,atmosphere:[1.0,0.0,0.0,0.0],sun:Vec4::Y,views:&views};let mut encoder=device.create_command_encoder(&Default::default());renderer.render(&queue,&mut encoder,&view,&params);encoder.copy_texture_to_buffer(target.as_image_copy(),wgpu::TexelCopyBufferInfo{buffer:&read,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(size.0*4),rows_per_image:Some(size.1)}},target.size());queue.submit([encoder.finish()]);read.slice(..).map_async(wgpu::MapMode::Read,|r|r.unwrap());device.poll(wgpu::PollType::wait_indefinitely()).unwrap();let map=read.slice(..).get_mapped_range().unwrap();let pixels=map.to_vec();drop(map);read.unmap();if !name.is_empty(){let mut png=png::Encoder::new(std::fs::File::create(root.join(name)).unwrap(),size.0,size.1);png.set_color(png::ColorType::Rgba);png.set_depth(png::BitDepth::Eight);png.write_header().unwrap().write_image_data(&pixels).unwrap();}pixels
 };
 let puff=ParticleDraw{position:Vec4::new(8.0,4.0,8.0,8.0),radius:0.8,thickness:0.8,uv:[56.0/256.0,0.0,63.99/256.0,7.99/256.0],color:[1.0;3],layer:28,light:[0,15]};
 let baseline=render(&mut renderer,&[],0,"negative-corner-macro.png");
 let reference=render(&mut renderer,&[],flags::REFERENCE_VOXEL_STEPS,"negative-corner-voxel.png");
 let geometry_mismatch=baseline.chunks_exact(4).zip(reference.chunks_exact(4)).filter(|(a,b)|a.iter().zip(b.iter()).any(|(&x,&y)|x.abs_diff(y)>3)).count();
 assert!(geometry_mismatch<100,"negative macrocell corner lost wall geometry in{geometry_mismatch}pixels");let front=render(&mut renderer,&[puff],0,"particles-explosion-main-aux.png");let behind=render(&mut renderer,&[ParticleDraw{position:Vec4::new(8.0,4.0,12.0,8.0),..puff}],0,"particles-occluded.png");
 let changed=baseline.chunks_exact(4).zip(front.chunks_exact(4)).filter(|(a,b)|a.iter().zip(b.iter()).any(|(&x,&y)|x.abs_diff(y)>3)).count();assert!(changed>100,"visible native sprite must render:{changed}");assert!(baseline.iter().zip(&behind).all(|(&a,&b)|a.abs_diff(b)<=3),"wall must fully occlude farther particles");
 let main_only=ParticleDraw{position:Vec4::new(10.5,2.0,8.0,8.0),radius:0.4,thickness:0.2,..puff};let isolated=render(&mut renderer,&[main_only],0,"particles-inset-isolation.png");let r=views[1].rect;for y in r[1].ceil()as usize..(r[1]+r[3]).floor()as usize{for x in r[0].ceil()as usize..(r[0]+r[2]).floor()as usize{let i=(y*size.0 as usize+x)*4;assert!(baseline[i..i+3].iter().zip(&isolated[i..i+3]).all(|(&a,&b)|a.abs_diff(b)<=3),"main-view sprite leaked into auxiliary view");}}
 let tile=block::texture_tile(block::BRICK.into(),2);let u=(tile%16)as f32*16.0+4.0;let v=(tile/16)as f32*16.0+4.0;let debris=ParticleDraw{position:Vec4::new(7.0,4.0,8.0,8.0),radius:0.4,thickness:0.2,layer:0,uv:[u/256.0,v/256.0,(u+3.996)/256.0,(v+3.996)/256.0],color:[0.6;3],..puff};let splash=ParticleDraw{position:Vec4::new(8.6,4.0,8.0,8.0),radius:0.4,thickness:0.8,uv:[32.0/256.0,8.0/256.0,39.99/256.0,15.99/256.0],..puff};
 render(&mut renderer,&[debris,splash],0,"particles-debris-splash.png");renderer.resize(&device,size,0.75);let stereo=render(&mut renderer,&[puff,debris,splash],flags::ANAGLYPH,"particles-stereo-scaled.png");assert!(stereo.iter().any(|&v|v>0));
}
